<?php
/**
 * Compute a signed sum of unique prime values found in $arr.
 *
 * For each unique value v in $arr:
 *  - consider it a "prime candidate" if abs(v) is prime
 *  - if the value occurs an even number of times in $arr, add v to the sum
 *  - if it occurs an odd number of times, add -v to the sum (flip its sign)
 * If no prime candidates are found, return null.
 *
 * This mirrors the behavior of the provided Python function.
 *
 * @param array $arr Array of integers.
 * @return int|null Signed sum of unique prime values, or null if none.
 */
function prod_signs(array $arr) {
    // Helper: check primality for a non-negative integer n
    $is_prime = function(int $n): bool {
        // Numbers less than 2 are not prime
        if ($n < 2) {
            return false;
        }
        // Test divisors from 2 up to floor(sqrt(n))
        $limit = (int) floor(sqrt($n));
        for ($i = 2; $i <= $limit; $i++) {
            if ($n % $i === 0) {
                return false; // composite
            }
        }
        return true; // prime
    };

    // Build a list of unique values from the original array.
    // Using unique values ensures each candidate is considered once (like set(arr) in Python).
    $unique = array_values(array_unique($arr));

    // Filter unique values to those whose absolute value is prime.
    // We preserve the original sign (so -3 remains -3 if present), just test abs for primality.
    $primes = [];
    foreach ($unique as $val) {
        if ($is_prime(abs($val))) {
            $primes[] = $val;
        }
    }

    // If no prime candidates, return null (matches Python's None).
    if (empty($primes)) {
        return null;
    }

    // Compute the sum according to the occurrence parity rule:
    // - If the original array contains the value an even number of times, add the value as-is.
    // - If it contains the value an odd number of times, add the negated value.
    $sum = 0;
    foreach ($primes as $p) {
        // Count occurrences of $p in the original array ($arr).
        $count = 0;
        foreach ($arr as $a) {
            if ($a === $p) {
                $count++;
            }
        }

        // Even occurrences => keep sign; odd occurrences => flip sign
        if ($count % 2 === 0) {
            $sum += $p;
        } else {
            $sum += -$p;
        }
    }

    return $sum;
}

