        tooltip.style.top = top + 'px';
        tooltip.style.display = 'block';
        tooltip.setAttribute('aria-hidden', 'false');
      }

      function hide() {
        tooltip.style.display = 'none';
        tooltip.setAttribute('aria-hidden', 'true');
      }

      function onMouseEnter(e) { showAt(e.clientX, e.clientY); }
      function onMouseMove(e) { showAt(e.clientX, e.clientY); }
      function onMouseLeave() { hide(); }

      // mouse
      icon.addEventListener('mouseenter', onMouseEnter);
      icon.addEventListener('mousemove', onMouseMove);
      icon.addEventListener('mouseleave', onMouseLeave);

      // keyboard — show tooltip centered above icon when focused
