Option A — type-sensitive (strict): matches only when type and value are identical. This keeps behavior predictable and avoids surprises when types mix.

Option B — type-flexible (coercing where safe): tries a sensible conversion (e.g., numeric string "3" → number 3) so the search succeeds even if the search value is a different type. This may be more convenient but should be chosen with team agreement.

Below is a small script showing both approaches and the expected output for your example array and search element.

Code:

const arr = [1, 2, 3, 4, 5, 5, 4, 3, 2, 1];
const search = "3";

// Strict (type-sensitive)
function existsStrict(a, s) {
  return a.includes(s); // uses strict equality (===)
}

// Flexible (tries safe conversions)
function existsFlexible(a, s) {
  if (a.includes(s)) return true; // already matches strictly

  // If the array seems to contain only numbers, try converting search to Number
  const allNumbers = a.every(item => typeof item === 'number' && Number.isFinite(item));
  if (allNumbers) {
    const n = Number(s);
    if (!Number.isNaN(n)) return a.includes(n);
  }

  // If the array contains only strings, compare as strings
  const allStrings = a.every(item => typeof item === 'string');
  if (allStrings) {
    return a.includes(String(s));
  }

  // Fallback: loose equality (==) for mixed arrays - use with awareness of its caveats
  return a.some(item => item == s);
}

// Helper to list all matching indices (flexible)
function findAllIndicesFlexible(a, s) {
  const indices = [];
  const allNumbers = a.every(item => typeof item === 'number' && Number.isFinite(item));
  let compare;
  if (a.includes(s)) {
    compare = x => x === s;
  } else if (allNumbers) {
    const n = Number(s);
    if (!Number.isNaN(n)) compare = x => x === n;
    else compare = x => x == s;
  } else {
    compare = x => x == s;
  }
  a.forEach((item, i) => { if (compare(item)) indices.push(i); });
  return indices;
}

// Results for your example
console.log('Strict exists:', existsStrict(arr, search)); // false
console.log('Flexible exists:', existsFlexible(arr, search)); // true
console.log('Flexible indices:', findAllIndicesFlexible(arr, search)); // [2, 7]

