Approach summary (quiet reasoning, for shared understanding)
- Compute target = first xor second for each query.
- Any substring value we might need fits in at most 30 bits (since inputs ≤ 1e9), so we only need to examine substrings of s with length ≤ 30.
- Precompute, for every integer value obtainable from any substring of length ≤ 30, the earliest (leftmost) shortest substring [left, right] that yields it. "Earliest" is used when multiple substrings have same minimal length.
- Then answer each query by looking up target in the precomputed map; if missing, return [-1, -1].
- This keeps per-query cost O(1) after O(n * 30) preprocessing (n = length(s)), which is reasonable for the constraints.

The code below follows that plan. I kept indices 0-based in results to match the problem statement and used Generics.Collections for a clean dictionary mapping.

Object Pascal (Delphi / FPC with Generics) implementation

uses
  SysUtils, Math, Generics.Collections;

type
  TIntArray = TArray<Integer>;
  TArrArr = TArray<TIntArray>;

function SubstringXorQueries(const s: string; const queries: TArrArr): TArrArr;
var
  n, i, j, maxLen, curVal, curLen: Integer;
  mp: TDictionary<Integer, TIntArray>;
  existing, tmp: TIntArray;
  key: Integer;
begin
  n := Length(s);
  maxLen := 30; // enough to cover values up to 1e9 (30 bits)
  mp := TDictionary<Integer, TIntArray>.Create;
  try
    // Precompute: for every start index, accumulate up to maxLen bits
    for i := 1 to n do
    begin
      curVal := 0;
      for j := i to Min(n, i + maxLen - 1) do
      begin
        // build binary value from s[i..j]; s is 1-based here
        curVal := (curVal shl 1) + Ord(s[j] = '1');

        if not mp.TryGetValue(curVal, existing) then
        begin
          // store 0-based endpoints
          mp.Add(curVal, TArray<Integer>.Create(i - 1, j - 1));
        end
        else
        begin
          curLen := existing[1] - existing[0] + 1;
          if (j - i + 1) < curLen then
            mp.Items[curVal] := TArray<Integer>.Create(i - 1, j - 1)
          else if ((j - i + 1) = curLen) and (i - 1 < existing[0]) then
            mp.Items[curVal] := TArray<Integer>.Create(i - 1, j - 1);
        end;
      end;
    end;

    // Answer queries by lookup
    SetLength(Result, Length(queries));
    for i := 0 to High(queries) do
    begin
      key := queries[i][0] xor queries[i][1];
      if mp.TryGetValue(key, tmp) then
        Result[i] := TArray<Integer>.Create(tmp[0], tmp[1])
      else
        Result[i] := TArray<Integer>.Create(-1, -1);
    end;

  finally
    mp.Free;
  end;
end;

// Example usage (small test harness)
procedure PrintArr(const a: TIntArray);
begin
  Write('[', a[0], ',', a[1], ']');
end;

procedure RunExample(const s: string; const queries: TArrArr);
var
  res: TArrArr;
  i: Integer;
begin
  res := SubstringXorQueries(s, queries);
  for i := 0 to High(res) do
  begin
    PrintArr(res[i]);
    if i < High(res) then Write(', ');
  end;
  Writeln;
end;

begin
  try
    // Example 1
    RunExample('101101', TArrArr.Create(
      TIntArray.Create(0,5),
      TIntArray.Create(1,2)
    )); // expected [[0,2],[2,3]]

    // Example 2
    RunExample('0101', TArrArr.Create(
      TIntArray.Create(12,8)
    )); // expected [[-1,-1]]

    // Example 3
    RunExample('1', TArrArr.Create(
      TIntArray.Create(4,5)
    )); // expected [[0,0]]

  except
    on E: Exception do
      Writeln('Error: ', E.ClassName, ': ', E.Message);
  end;
end.

