Swift translation (Unicode-safe substring handling):

func allSubstrings(_ input: String) -> [String] {
    var substrings: [String] = []
    let charsIndices = Array(input.indices)
    let n = charsIndices.count

    for i in 0..<n {
        for j in i..<n {
            let substring = String(input[charsIndices[i]...charsIndices[j]])
            substrings.append(substring)
        }
    }
    return substrings
}

func longestSubstring(in strings: [String], k: Int) -> String? {
    guard !strings.isEmpty else { return nil }

    var longest: String = ""
    for s in strings {
        for substr in allSubstrings(s) {
            var count = 0
            for str in strings {
                if str.contains(substr) { count += 1 }
            }
            if count >= k && substr.count > longest.count {
                longest = substr
            }
        }
    }
    return longest.isEmpty ? nil : longest
}

