function sortBooks(books) {
  // Attach original index so we can preserve original order for perfect ties
  const items = books.map((title, index) => ({ title, index }));

  items.sort((a, b) => {
    const A = a.title;
    const B = b.title;

    // Use the very first character of the string (case-sensitive)
    const aFirst = A.length ? A[0] : '';
    const bFirst = B.length ? B[0] : '';

    // If different starting character -> compare by char code (numbers come before letters)
    if (aFirst !== bFirst) {
      const ac = aFirst ? aFirst.charCodeAt(0) : -Infinity;
      const bc = bFirst ? bFirst.charCodeAt(0) : -Infinity;
      return ac - bc;
    }

    // Same starting character -> sort by length descending
    if (A.length !== B.length) {
      return B.length - A.length;
    }

    // Same starting character and same length -> sort by ASCII values descending (lexicographic by code units)
    if (A !== B) {
      // For descending order, invert the usual comparison
      if (A < B) return 1;
      if (A > B) return -1;
    }

    // Perfect tie -> keep original order
    return a.index - b.index;
  });

  // Return sorted titles
  return items.map(i => i.title);
}

