import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/**
 * 表示一个团队成员
 */
class Member {
    private String name;
    private String role;
    private int age;

    // 默认构造函数
    public Member() {
        this("Unknown", "Member", 0);
    }

    // 带参数的构造函数
    public Member(String name, String role, int age) {
        this.name = name;
        this.role = role;
        this.age = age;
    }

    // Getter / Setter（简化示例，只给出必要的）
    public String getName() {
        return name;
    }

    public String getRole() {
        return role;
    }

    public int getAge() {
        return age;
    }

    @Override
    public String toString() {
        return String.format("%s (%s, %d)", name, role, age);
    }
}

/**
 * 表示一个团队，包含多个成员
 */
class Team {
    private String teamName;
    private List<Member> members;
    private Member leader; // 可选的领导/组长

    // 无参构造：使用默认名称
    public Team() {
        this("Unnamed Team", new ArrayList<>());
    }

    // 只提供名称的构造函数
    public Team(String teamName) {
        this(teamName, new ArrayList<>());
    }

    // 提供名称和成员列表的构造函数
    public Team(String teamName, List<Member> members) {
        this.teamName = teamName;
        // 为了避免外部直接修改，复制一份列表
        this.members = new ArrayList<>(members);
        if (!this.members.isEmpty()) {
            this.leader = this.members.get(0); // 约定：列表第一个为临时leader
        }
    }

    // 添加成员（返回是否添加成功）
    public boolean addMember(Member m) {
        if (m == null) return false;
        return members.add(m);
    }

    // 根据名字移除成员（间接沟通：避免直接冲突）
    public boolean removeMemberByName(String name) {
        Iterator<Member> it = members.iterator();
        while (it.hasNext()) {
            if (it.next().getName().equals(name)) {
                it.remove();
                // 若移除的是leader，尝试调整leader为第一位
                if (leader != null && leader.getName().equals(name)) {
                    leader = members.isEmpty() ? null : members.get(0);
                }
                return true;
            }
        }
        return false;
    }

    // 设置领导
    public void setLeader(Member leader) {
        if (leader != null && members.contains(leader)) {
            this.leader = leader;
        }
    }

    // 可以通过名字设置领导（更常见的实际用法）
    public boolean setLeaderByName(String name) {
        for (Member m : members) {
            if (m.getName().equals(name)) {
                this.leader = m;
                return true;
            }
        }
        return false;
    }

    // 获取平均年龄（示例方法）
    public double getAverageAge() {
        if (members.isEmpty()) return 0.0;
        int sum = 0;
        for (Member m : members) sum += m.getAge();
        return (double) sum / members.size();
    }

    public int getMemberCount() {
        return members.size();
    }

    // 打印团队信息（间接、尊重群体）
    public String getTeamInfo() {
        StringBuilder sb = new StringBuilder();
        sb.append("Team: ").append(teamName).append("\n");
        sb.append("Leader: ").append(leader == null ? "None" : leader).append("\n");
        sb.append("Members (").append(getMemberCount()).append("):\n");
        for (Member m : members) {
            sb.append(" - ").append(m).append("\n");
        }
        sb.append(String.format("Average age: %.2f\n", getAverageAge()));
        return sb.toString();
    }
}

/**
 * 演示用法
 */
public class TeamDemo {
    public static void main(String[] args) {
        // 创建多个 Member 对象（多个对象示例）
        Member alice = new Member("Alice", "Developer", 28);
        Member bob = new Member("Bob", "Tester", 32);
        Member carol = new Member("Carol", "Designer", 26);

        // 用不同构造函数创建 Team
        Team t1 = new Team(); // 无参构造
        t1.addMember(alice);
        t1.addMember(bob);
        t1.setLeader(alice);

        System.out.println(t1.getTeamInfo());

        // 使用带参数的构造函数（直接传入成员列表）
        List<Member> list = new ArrayList<>();
        list.add(bob);
        list.add(carol);
        Team t2 = new Team("Product Team", list);
        t2.setLeaderByName("Carol");

        System.out.println(t2.getTeamInfo());

        // 展示移除成员
        t2.removeMemberByName("Bob");
        System.out.println("After removal:");
        System.out.println(t2.getTeamInfo());
    }
}
